package db

import (
	"database/sql/driver"
	"encoding/json"
	"fmt"
	"math/big"
	"time"

	"github.com/google/uuid"
)

// UUID is the store's portable UUID value. It keeps the field shape the
// previous pgx type exposed (Bytes/Valid) without depending on pgx; IDs are
// generated by the application.
type UUID struct {
	Bytes [16]byte
	Valid bool
}

// String renders the canonical UUID, or "" when invalid.
func (u UUID) String() string {
	if !u.Valid {
		return ""
	}
	return uuid.UUID(u.Bytes).String()
}

// Scan implements sql.Scanner.
func (u *UUID) Scan(value any) error {
	switch v := value.(type) {
	case nil:
		*u = UUID{}
	case [16]byte:
		u.Bytes, u.Valid = v, true
	case []byte:
		if len(v) == 16 {
			copy(u.Bytes[:], v)
			u.Valid = true
			return nil
		}
		return u.parse(string(v))
	case string:
		return u.parse(v)
	default:
		return fmt.Errorf("db.UUID: cannot scan %T", value)
	}
	return nil
}

func (u *UUID) parse(s string) error {
	parsed, err := uuid.Parse(s)
	if err != nil {
		return err
	}
	u.Bytes, u.Valid = [16]byte(parsed), true
	return nil
}

// Value implements driver.Valuer.
func (u UUID) Value() (driver.Value, error) {
	if !u.Valid {
		return nil, nil
	}
	return uuid.UUID(u.Bytes).String(), nil
}

// MarshalJSON renders the canonical UUID string, or null when invalid. It
// matches the wire shape the store's types carried before GORM (workflow
// payloads and stored JSON keep the same IDs).
func (u UUID) MarshalJSON() ([]byte, error) {
	if !u.Valid {
		return []byte("null"), nil
	}
	return json.Marshal(u.String())
}

// UnmarshalJSON reads a UUID string, or null.
func (u *UUID) UnmarshalJSON(data []byte) error {
	var s *string
	if err := json.Unmarshal(data, &s); err != nil {
		return err
	}
	if s == nil {
		*u = UUID{}
		return nil
	}
	return u.parse(*s)
}

// Timestamptz is a nullable instant.
type Timestamptz struct {
	Time  time.Time
	Valid bool
}

// Scan implements sql.Scanner.
func (t *Timestamptz) Scan(value any) error {
	switch v := value.(type) {
	case nil:
		*t = Timestamptz{}
	case time.Time:
		t.Time, t.Valid = v, true
	case []byte:
		return t.parse(string(v))
	case string:
		return t.parse(v)
	default:
		return fmt.Errorf("db.Timestamptz: cannot scan %T", value)
	}
	return nil
}

func (t *Timestamptz) parse(s string) error {
	for _, layout := range []string{
		time.RFC3339Nano,
		"2006-01-02 15:04:05.999999999-07",
		"2006-01-02 15:04:05.999999-07",
		"2006-01-02 15:04:05.999999",
		"2006-01-02 15:04:05",
	} {
		if parsed, err := time.Parse(layout, s); err == nil {
			t.Time, t.Valid = parsed, true
			return nil
		}
	}
	return fmt.Errorf("db.Timestamptz: cannot parse %q", s)
}

// Value implements driver.Valuer.
func (t Timestamptz) Value() (driver.Value, error) {
	if !t.Valid {
		return nil, nil
	}
	return t.Time, nil
}

// MarshalJSON renders the instant as RFC 3339, or null when invalid.
func (t Timestamptz) MarshalJSON() ([]byte, error) {
	if !t.Valid {
		return []byte("null"), nil
	}
	return json.Marshal(t.Time.Format(time.RFC3339Nano))
}

// UnmarshalJSON reads an RFC 3339 instant, or null.
func (t *Timestamptz) UnmarshalJSON(data []byte) error {
	var s *string
	if err := json.Unmarshal(data, &s); err != nil {
		return err
	}
	if s == nil {
		*t = Timestamptz{}
		return nil
	}
	return t.parse(*s)
}

// InfinityModifier is the sign of a non-finite Numeric.
type InfinityModifier int8

const (
	// Finite is an ordinary numeric value.
	Finite InfinityModifier = 0
	// Infinity is positive infinity.
	Infinity InfinityModifier = 1
	// NegativeInfinity is negative infinity.
	NegativeInfinity InfinityModifier = -1
)

// Numeric is a nullable arbitrary-precision decimal. It keeps the field shape
// the retired pgx numeric exposed, without depending on pgx.
type Numeric struct {
	Int              *big.Int
	Exp              int32
	NaN              bool
	InfinityModifier InfinityModifier
	Valid            bool
}

// Interval is a nullable time interval.
type Interval struct {
	Months       int32
	Days         int32
	Microseconds int64
	Valid        bool
}

// Scan implements sql.Scanner.
func (i *Interval) Scan(value any) error {
	switch v := value.(type) {
	case nil:
		*i = Interval{}
	case []byte:
		return i.parse(string(v))
	case string:
		return i.parse(v)
	default:
		return fmt.Errorf("db.Interval: cannot scan %T", value)
	}
	return nil
}

func (i *Interval) parse(s string) error {
	// The driver normally hands intervals back as a string; the store path only
	// reads them, so keep the raw microseconds when the form is recognised.
	if _, err := fmt.Sscanf(s, "%d", &i.Microseconds); err != nil {
		return fmt.Errorf("db.Interval: cannot parse %q", s)
	}
	i.Valid = true
	return nil
}

// Value implements driver.Valuer.
func (i Interval) Value() (driver.Value, error) {
	if !i.Valid {
		return nil, nil
	}
	return fmt.Sprintf("%d microseconds", i.Microseconds), nil
}
